import { h, render, Component } from 'preact';

import constants from './../constants';

class CreateForm extends Component {

  constructor(props) {
    super(props);

    this.state = {
      variables_: [],

      variables: []
    };
  }  

  componentDidMount() {
    this.getVariables();

    let o = this.props.item;
    if (o) {
      let inputName = document.querySelector('#input-u-name');
      let inputDevice = document.querySelector('#input-u-device');
      let inputUnit = document.querySelector('#input-u-unit');
      let inputStatus = document.querySelector('#input-u-status');

      inputName.value = o.name;
      inputDevice.value = o.device;
      inputUnit.value = o.unit;
      inputStatus.checked = o.status;
    }    
  }

  replaceAll(s, old, n) {
    s = s.replace(old, n);

    let i = s.indexOf(old);
    if (i >= 0) {
      this.replaceAll(s, old, n);
    }

    return s
  }  

  getVariables() {
    let self = this;

    let url = `${constants.URL_SERVER_VARIABLES}/list`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ variables_: res.docs }, () => {
          let o = self.props.item;
          if (o) {
            let expression = o.expression;

            let variablesIn = o.variables_json;
            if (variablesIn) {
              let variables = [];
              for (let i = 0; i < variablesIn.length; i++) {
                const id = variablesIn[i];
                let variables_ = self.state.variables_;
                for (let j = 0; j < variables_.length; j++) {
                  const variable_ = variables_[j];
                  if (id == variable_.id) {
                    variables.push(variable_);

                    let old = '${'+ id +'}';
                    let n = '${' + variable_.device + '.' + variable_.name + '}';
                    expression = self.replaceAll(expression, old, n)
                  }
                } 
              }

              if (variables.length > 0) self.setState({ variables: variables });
            }

            let inputExpression = document.querySelector('#input-u-expression');
            inputExpression.value = expression;
          }
        });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  handleUpdate() {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();

      let o = self.props.item;
      if (!o) {
        alert('No se encontro la información de la variable');
        return;
      }

      let inputName = document.querySelector('#input-u-name');
      let inputDevice = document.querySelector('#input-u-device');
      let inputExpression = document.querySelector('#input-u-expression');
      let inputUnit = document.querySelector('#input-u-unit');
      let inputStatus = document.querySelector('#input-u-status');

      let name = inputName.value.trim();
      let device = inputDevice.value.trim();
      let expression = inputExpression.value.trim();
      let unit = inputUnit.value.trim();
      let status = inputStatus.checked;

      let variables = self.state.variables;
      let size = variables.length;
      if (size == 0) {
        alert('La lista de variables esta vacia');
        return;
      }

      if (expression == '') {
        alert('La expresión es nula');
        
        return;
      }

      let variables_json = [];
      for (let i = 0; i < size; i++) {
        const variable = variables[i];
        let id = variable.id;
        if (id) {
          let old = '${' + variable.device + '.' + variable.name + '}';
          let n = '${' + id + '}';

          expression = self.replaceAll(expression, old, n)

          let v = parseInt(id);
          variables_json.push(v);
        }
      }

      let json = {};

      json.name = name;
      json.device = device;
      json.expression = expression;
      json.unit = unit;
      json.status = status;
      json.variables_json = variables_json;

      let id = o.id;
      
      self.props.onUpdate(json, id);
    };

    return fn;
  }

  handleInsert() {
    let self = this;

    let fn = () => {
      let inputVariable = document.querySelector('#input-variable');
      let sId = inputVariable.value.trim();

      let id = parseInt(sId);

      let variables = self.state.variables;
      for (let i = 0; i < variables.length; i++) {
        const variable = variables[i];
        if (variable.id == id) return;
      }

      let items = self.state.variables_;
      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        if (item.id == id) {
          variables.push(item);
          break;
        }
      }

      self.setState({ variables: variables });
    };

    return fn;
  }

  handleRemove(id) {
    let self = this;

    let fn = () => {
      let variables = self.state.variables;
      for (let i = 0; i < variables.length; i++) {
        const variable = variables[i];
        if (variable.id == id) {
          variables.splice(i, 1);
          self.setState({ variables: variables });

          return;
        }
      }
    };

    return fn;
  }  

  handleBack() {
    let self = this;

    let fn = () => {
      self.props.onBack();
    };

    return fn;
  }

  createOptName() {
    let self = this;

    let fn = (item, index) => {
      return <option key={item.id} value={item.id}>{item.device}.{item.name}</option>;
    };

    return fn;
  }

  createItem() {
    let self = this;

    let fn = (item, index) => {
      return (
        <li className="list-group-item" key={item.id}>
          {item.device}.{item.name}
          <button type="button" className="close" data-dismiss="modal" aria-label="Close" onClick={self.handleRemove(item.id)}>
            <span aria-hidden="true">&times;</span>
          </button>
        </li>
      );
    };

    return fn;
  }

  render(props, state) {
    return (
      <section>
        <div className="row">
          <div className="col-md-12">
            <h3>Editar Variable Personalizada</h3>

            <form onSubmit={this.handleUpdate()} >

              <div className="form-group">
                <label htmlFor="input-u-name">Nombre</label>
                <input type="text" className="form-control" id="input-u-name" placeholder="Nombre" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-device">Dispositivo</label>
                <input type="text" className="form-control" id="input-u-device" placeholder="Dispositivo" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-expression">
                  Expresión Aritmetica
                  <br />
                  {'${DEVICE.VARIABLE}: Clave de la variable'}
                </label>
                <textarea type="text" className="form-control" id="input-u-expression" placeholder="Expresión" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-unit">Unidad</label>
                <input type="text" className="form-control" id="input-u-unit" placeholder="Ejemplo: Pa, Km/cm2, PSI" />
              </div>

              <div className="form-check">
                <input type="checkbox" class="form-check-input" id="input-u-status" />
                <label class="form-check-label" htmlFor="input-u-status">Estatus</label>
              </div>


              <div className="row">

                <div className="col-md-4">
                  <select class="form-control" id="input-variable">
                    <option>Variables</option>
                    {state.variables_.map(this.createOptName())}
                  </select>
                </div>

                <div className="col-md-8">
                  <button type="button" className="btn btn-primary" onClick={this.handleInsert()}>
                    <i className="material-icons">add</i>
                  </button>
                </div>

                <div className="col-md-12" style={{ marginTop: '10px' }}>
                  <ul className="list-group">
                    {state.variables.map(this.createItem())}
                  </ul>
                </div>

              </div>

              <div className="form-group col-md-12">
                <br />
                <br />
                <button type="button" className="btn btn-warning" onClick={this.handleBack()}>Cancelar</button>
                <button type="submit" className="btn btn-primary">Guardar cambios</button>
              </div>

            </form>

          </div>
        </div>
      </section>
    );
  }
}

export default CreateForm;
