import { h, render, Component } from 'preact';
import { isString } from 'underscore';

import constants from './../constants';

class CreateForm extends Component {

  constructor(props) {
    super(props);

    this.state = {
      variables_: [],

      variables: []
    };
  }

  componentDidMount() {
    this.getVariables();
  }

  replaceAll(s, old, n) {
    s = s.replace(old, n);

    let i = s.indexOf(old);
    if (i >= 0) {
      this.replaceAll(s, old, n);
    }

    return s
  }

  getVariables() {
    let self = this;

    let url = `${constants.URL_SERVER_VARIABLES}/list`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ variables_: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }  

  handleCreate() {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();

      let inputName = document.querySelector('#input-c-name');
      let inputDevice = document.querySelector('#input-c-device');
      let inputExpression = document.querySelector('#input-c-expression');
      let inputUnit = document.querySelector('#input-c-unit');
      let inputStatus = document.querySelector('#input-c-status');

      let name = inputName.value.trim();
      let device = inputDevice.value.trim();
      let expression = inputExpression.value.trim();
      let unit = inputUnit.value.trim();
      let status = inputStatus.checked;

      let variables = self.state.variables;
      let size = variables.length;
      if (size == 0) {
        alert('La lista de variables esta vacia');
        return;
      }

      if (expression == '') {
        alert('La expresión es nula');
        return;
      }

      let variables_json = [];
      for (let i = 0; i < size; i++) {
        const variable = variables[i];
        let id = variable.id;

        if (id) {
          let old = '${' + variable.device + '.' + variable.name + '}';
          let n = '${' + id + '}';

          expression = self.replaceAll(expression, old, n)

          let v = parseInt(id);
          variables_json.push(v)
        }
      }

      let json = {};

      json.name = name;
      json.device = device;
      json.expression = expression;
      json.unit = unit;
      json.status = status;
      json.variables_json = variables_json;

      self.props.onCreate(json);
    };

    return fn;
  }

  handleInsert() {
    let self = this;

    let fn = () => {
      let inputVariable = document.querySelector('#input-variable');
      let sId = inputVariable.value.trim();

      let id = parseInt(sId);

      let variables = self.state.variables;
      for (let i = 0; i < variables.length; i++) {
        const variable = variables[i];
        if (variable.id == id) return;
      }

      let items = self.state.variables_;
      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        if (item.id == id) {
          variables.push(item);

          break;
        }
      }

      self.setState({ variables: variables });
    };

    return fn;
  }

  handleRemove(id) {
    let self = this;

    let fn = () => {
      let variables = self.state.variables;
      for (let i = 0; i < variables.length; i++) {
        const variable = variables[i];
        if (variable.id == id) {
          variables.splice(i, 1);
          self.setState({ variables: variables });

          return;
        }
      }
    };

    return fn;
  }

  handleBack() {
    let self = this;

    let fn = () => {
      self.props.onBack();
    };

    return fn;
  }

  createOptName() {
    let self = this;

    let fn = (item, index) => {
      return <option key={item.id} value={item.id}>{item.device}.{item.name}</option>;
    };

    return  fn;
  }

  createItem() {
    let self = this;

    let fn = (item, index) => {
      return (
        <li className="list-group-item" key={item.id}>
          {item.device}.{item.name}
          <button type="button" className="close" data-dismiss="modal" aria-label="Close" onClick={self.handleRemove(item.id)}>
            <span aria-hidden="true">&times;</span>
          </button>
        </li>
      );
    };

    return fn;    
  }

  render(props, state) {
    return (
      <section>
        <div className="row">
          <div className="col-md-12">
            <h3>Crear Variable Personalizada</h3>

            <form onSubmit={this.handleCreate()} >

              <div className="form-group">
                <label htmlFor="input-c-name">Nombre</label>
                <input type="text" className="form-control" id="input-c-name" placeholder="Nombre" />
              </div>

              <div className="form-group">
                <label htmlFor="input-c-device">Dispositivo</label>
                <input type="text" className="form-control" id="input-c-device" placeholder="Dispositivo" />
              </div>

              <div className="form-group">
                <label htmlFor="input-c-expression">
                  Expresión Aritmetica
                  <br />
                  {'${DEVICE.VARIABLE}: Clave de la variable'}
                </label>
                <textarea type="text" className="form-control" id="input-c-expression" placeholder="Expresión" />
              </div>

              <div className="form-group">
                <label htmlFor="input-c-unit">Unidad</label>
                <input type="text" className="form-control" id="input-c-unit" placeholder="Ejemplo: Pa, Kg/cm2, PSI" />
              </div>

              <div className="form-check">
                <input type="checkbox" class="form-check-input" id="input-c-status" />
                <label class="form-check-label" htmlFor="input-c-status">Estatus</label>
              </div>


              <div className="row" style={{ marginTop: '10px' }}>

                <div className="col-md-4">
                  <select class="form-control" id="input-variable">
                    <option>Variables</option>
                    {state.variables_.map(this.createOptName())}
                  </select>
                </div>

                <div className="col-md-8">
                  <button type="button" className="btn btn-primary" onClick={this.handleInsert()}>
                    <i className="material-icons">add</i>
                  </button>
                </div>

                <div className="col-md-12" style={{ marginTop: '10px' }}>
                  <ul className="list-group">
                    {state.variables.map(this.createItem())}
                  </ul>
                </div>

              </div>

              <div className="form-group col-md-12">
                <br />
                <br />
                <button type="button" className="btn btn-warning" onClick={this.handleBack()}>Cancelar</button>
                <button type="submit" className="btn btn-success">Guardar</button>
              </div>

            </form>
            
          </div>
        </div>
      </section>
    );
  }
}

export default CreateForm;
