import { h, render, Component } from 'preact';

import constants from './../constants.js';

import Table from './table.jsx';
import CreateForm from './create-form.jsx';
import UpdateForm from './update-form.jsx';

const ENTER = 13;
const TABLE = 0;
const CREATE_FORM = 1;
const UPDATE_FORM = 2;

class Content extends Component {

  constructor() {
    super();

    this.state = {
      items: [],
      item: false,
      search: '',
      form: TABLE
    };
  }

  componentDidMount() {
    this.getCustomVariables();
  }

  getCustomVariables() {
    let self = this;

    let url = `${constants.URL_SERVER_CUSTOM_VARIABLES}/list`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ items: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  getCustomVariablesForSearch(value) {
    let self = this;

    let url = `${constants.URL_SERVER_CUSTOM_VARIABLES}/list?search=${value}`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ items: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  getCustomVariable() {
    let self = this;

    let fn = (json) => {
      let xhr = $.ajax({
        url: `${constants.URL_SERVER_CUSTOM_VARIABLES}/${json.id}`,
        type: constants.METHOD_GET,
        dataType: constants.JSON
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_OK) {
          self.getItem(null, res.doc);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.getItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    };

    return fn;
  }

  addCustomVariable() {
    let self = this;

    let fn = (json) => {
      let xhr = $.ajax({
        url: constants.URL_SERVER_CUSTOM_VARIABLES,
        type: constants.METHOD_POST,
        contentType: constants.APPLICATION_JSON,
        data: JSON.stringify(json)
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_CREATED) {
          self.addItem(null, res.doc);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.addItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    }

    return fn;
  }

  updateCustomVariable() {
    let self = this;

    let fn = (json, id) => {

      let xhr = $.ajax({
        url: `${constants.URL_SERVER_CUSTOM_VARIABLES}/${id}`,
        type: constants.METHOD_PUT,
        contentType: constants.APPLICATION_JSON,
        data: JSON.stringify(json)
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_OK) {
          self.updateItem(null, res.doc);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.updateItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    }

    return fn;
  }

  deleteCustomVariable() {
    let self = this;

    let fn = (json) => {
      let xhr = $.ajax({
        url: `${constants.URL_SERVER_CUSTOM_VARIABLES}/${json.id}`,
        type: constants.METHOD_DELETE
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_OK) {
          self.removeItem(null, json);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.removeItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    }

    return fn;
  }

  getItem(err, item) {
    let self = this;

    if (err) {
      alert(err);
      return;
    }

    self.setState({ item: item, form: UPDATE_FORM });
  }

  addItem(err, item) {
    if (err) {
      alert(err);
      return;
    }

    let items = this.state.items;
    items.push(item);
    this.setState({ form: TABLE, items: items });
  }

  updateItem(err, item) {
    if (err) {
      alert(err);
      return;
    }

    let items = this.state.items;
    for (let i = 0; i < items.length; i++) {
      let id = items[i].id;
      if (item.id == id) {
        items[i] = item;
        break;
      }
    }

    this.setState({ form: TABLE, items: items });
  }

  removeItem(err, item) {
    let self = this;

    if (!err) {
      let items = self.state.items;
      for (let i = 0; i < items.length; i++) {
        let id = items[i].id;
        if (item.id == id) {
          items.splice(i, 1);
          break;
        }
      }

      self.setState({ items: items });
    } else {
      alert(err);
    }
  }

  handleCreate() {
    let self = this;

    let fn = () => {
      self.setState({ form: CREATE_FORM });
    };

    return fn;
  }

  handleChange() {
    let self = this;

    let fn = (evt) => {
      let value = evt.target.value;
      let space = ' ';
      let re = new RegExp(space, 'g');
      let nil = '';

      value = value.replace(re, nil);
      if (value == '') {
        self.getCustomVariables();
      }
    };

    return fn;
  }

  handleSearch() {
    let self = this;

    let fn = (evt) => {
      if (evt.which == ENTER) {
        evt.preventDefault();
        let search = evt.target.value;
        if (search) {
          if (search !== '') {
            search = search.toLowerCase();
            self.getCustomVariablesForSearch(search);
          }
        }
      }
    };

    return fn;
  }

  handleBack() {
    let self = this;

    let fn = () => {
      let form = self.state.form;
      if (form == UPDATE_FORM) {
        self.setState({ form: TABLE, item: false });
        return;
      }

      self.setState({ form: TABLE });
    }

    return fn;
  }

  render(props, state) {
    let self = this;

    let view = false;
    let form = state.form;

    let createForm = <CreateForm onCreate={self.addCustomVariable()} onBack={self.handleBack()} />
    let updateForm = <UpdateForm item={state.item} onUpdate={self.updateCustomVariable()} onBack={self.handleBack()} />

    let table = (() => {
      return (
        <div>
          <div className="row">
            <div className="col-md-3">
              <h4>Variables Personalizadas</h4>
            </div>

            <div className="col-md-6">
              <div className="form-group col-md-12">
                <input placeholder="Buscar..." type="text" className="form-control" onInput={self.handleChange()} onKeyPress={self.handleSearch()} />
              </div>
            </div>

            <div className="col-md-3">
              <button type="button" className="btn btn-success" onClick={self.handleCreate()}>
                <i className="material-icons">add</i> Nuevo
              </button>
            </div>
          </div>

          <Table items={state.items} onGet={self.getCustomVariable()} onDelete={self.deleteCustomVariable()} />
        </div>
      );
    })();

    if (form == CREATE_FORM) {
      view = createForm;
    } else if (form == UPDATE_FORM) {
      view = updateForm;
    } else {
      view = table;
    }

    return (
      <div>
        {view}
      </div>
    );
  }
}

render(<Content />, document.getElementById('content-main'));